parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "type": {
      "type": "string",
      "enum": ["bug", "task", "feature", "unknown"],
      "description": "Category of the issue"
    },
    "confidence": {
      "type": "number",
      "description": "Confidence score between 0.0 and 1.0"
    },
    "reasoning": {
      "type": "string",
      "description": "Short explanation of the classification"
    }
  },
  "required": ["type", "confidence"]
}

parameters.jsCode:
// Normalize output fields for calling workflow
const item = $json.output || $json;
let type = (item.type || "unknown").toLowerCase().trim();
if (!["bug", "task", "feature", "unknown"].includes(type)) {
  type = "unknown";
}
let confidence = Number(item.confidence);
if (isNaN(confidence) || confidence < 0 || confidence > 1) {
  confidence = 0.5;
}

return [{
  json: {
    type: type,
    confidence: Math.round(confidence * 100) / 100,
    reasoning: item.reasoning || ""
  }
}];
